<?php
require_once __DIR__ . '/config.php';
require_once __DIR__ . '/functions.php';
$stmt = $pdo->query("SELECT l.id AS lost_id, l.item_name AS lost_name, l.category, l.location AS lost_location, l.item_date AS lost_date, f.id AS found_id, f.item_name AS found_name, f.location AS found_location, f.item_date AS found_date, f.created_at AS found_created FROM items l JOIN items f ON LOWER(l.category)=LOWER(f.category) WHERE l.report_type='lost' AND f.report_type='found' AND l.status='searching' AND f.status='available' ORDER BY (LOWER(l.item_name)=LOWER(f.item_name)) DESC, l.created_at DESC");
$matches = $stmt->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Potential Matches | CampusFind</title><link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet"><link rel="stylesheet" href="simple.css"></head><body><header class="site-header"><a class="brand" href="index.php"><span class="brand-icon">C</span><span><strong>CampusFind</strong><small>Lost &amp; Found</small></span></a><nav><a href="index.php">Dashboard</a><a href="items.php">All items</a><a href="report.php">Report an item</a><a href="admin_login.php">Admin</a></nav></header><main class="page-wrap wide"><a class="back-link" href="index.php">← Dashboard</a><h1>Potential Matches</h1><p class="muted intro-copy">These suggestions use matching categories only. They are leads for manual verification, not confirmed matches.</p>
<?php if (!$matches): ?><div class="table-card"><p class="empty-state">There are no potential matches right now. A suggestion appears when an open lost report and an available found report have the same category.</p></div><?php else: ?><div class="match-grid"><?php foreach ($matches as $match): ?><article class="match-card"><div class="match-pair"><div><span class="pill lost">Lost</span><h2><?= h($match['lost_name']) ?></h2><p>📍 <?= h($match['lost_location']) ?></p><small>Reported date: <?= h($match['lost_date']) ?></small></div><div class="match-symbol">↔</div><div><span class="pill found">Found</span><h2><?= h($match['found_name']) ?></h2><p>📍 <?= h($match['found_location']) ?></p><small>Reported date: <?= h($match['found_date']) ?></small></div></div><div class="match-footer"><span class="pill status-pill">Category: <?= h($match['category']) ?></span><span class="muted">Verify through campus administration before returning an item.</span></div></article><?php endforeach; ?></div><?php endif; ?>
</main></body></html>
